# Adds real sales visibility to the vendor dashboard: stat cards
# (total orders, total payout, avg order value), per-product
# breakdown, and a recent sales list. All queried from orders
# filtered to this vendor's own vendor_id.
$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\vendor\dashboard\page.tsx"), $bytes)
Write-Host "UPDATED: src\app\vendor\dashboard\page.tsx" -ForegroundColor Green
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan